// as_of = last completed trading session (ET). A session counts once 18:00 ET has passed.
// Sessions come from the Alpaca calendar; weekday math is the fallback when the call fails.
const j = $('Start run + watchlist').first().json;
const now = new Date();
const et = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
const iso = (x) => `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
let d = new Date(et);
if (et.getHours() < 18 || d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() - 1);
while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() - 1);
const today = iso(et);
const sessions = $input.all().map(i => i.json).filter(c => c && !c.error && /^\d{4}-\d{2}-\d{2}$/.test(String(c.date || ''))).map(c => c.date).sort();
const done = sessions.filter(s => s < today || (s === today && et.getHours() >= 18));
const calendar_ok = done.length > 0;
const as_of = calendar_ok ? done[done.length - 1] : iso(d);
const s = new Date(as_of + 'T12:00:00'); s.setDate(s.getDate() - 10);
return [{ json: { run_id: j.run_id, as_of, calendar_ok, av_ok_today: Number(j.av_ok_today || 0), tickers: j.tickers, benchmarks: j.benchmarks || [], weights: j.weights, holdings: j.holdings || [], positions: j.positions || {}, email_position_values: j.email_position_values === true, av_budget: 22, start: iso(s), end: as_of, days_back: 5 } }];

// Deterministic scoring. v2 = momentum + sentiment + growth-adjusted value + catalyst.
const SCORE_VERSION = 'v2';
const ctx = $('Build context').first().json;
const items = $input.all().map(i => i.json);
const isBench = (r) => (r.tags || []).includes('benchmark');
const bench = {}; for (const r of items) if (isBench(r)) bench[r.ticker] = r;
const num = (v) => (v == null || v === '' ? null : Number(v));
const clamp = (v, a = 0, b = 100) => Math.max(a, Math.min(b, v));
const r2 = (v) => (v == null ? null : Math.round(v * 100) / 100);
const qqq20 = num(bench.QQQ && bench.QQQ.ret_20d) || 0;
const w = ctx.weights || { momentum: 0.3, value: 0.25, sentiment: 0.25, catalyst: 0.2 };
// News rate per ticker (7-day articles per day over the 30-day baseline), then the watchlist median so surge is relative to the day, not to a still-filling baseline.
const rateOf = (r) => { const c = num(r.news_count) || 0, c30 = num(r.cnt_30d); return c30 == null || (c30 < 5 && c < 5) ? null : (c / 7) / Math.max(c30 / 30, 0.2); };
const rates = items.filter(r => !isBench(r)).map(rateOf).filter(v => v != null).sort((a, b) => a - b);
const medRate = rates.length ? rates[Math.floor(rates.length / 2)] : null;
const rows = [];
for (const r of items) {
  if (isBench(r)) continue;
  const close = num(r.close), sma20 = num(r.sma20), sma50 = num(r.sma50), sma200 = num(r.sma200), rsi = num(r.rsi14), volz = num(r.vol_z20);
  const r1 = num(r.ret_1d), r5 = num(r.ret_5d), r20 = num(r.ret_20d), news = num(r.news_score), base = num(r.sent_30d), cnt = num(r.news_count) || 0, hi20 = num(r.hi20_prev), fromHi = num(r.pct_from_hi52w), rsiPrevMax = num(r.rsi20_prev_max);
  const reasons = {};
  let m = null;
  if (close != null) {
    m = 50;
    if (sma200 != null) m += close > sma200 ? 10 : -10;
    if (sma50 != null) m += close > sma50 ? 8 : -8;
    if (sma50 != null && sma200 != null) m += sma50 > sma200 ? 7 : -7;
    if (rsi != null) m += clamp((rsi - 50) / 2, -15, 15);
    if (r20 != null) m += clamp((r20 - qqq20) * 100, -15, 15);
    if (volz != null && r1 != null) m += clamp(volz * Math.sign(r1) * 3, -5, 5);
    m = clamp(m);
    reasons.momentum = { vs_sma200: sma200 ? r2((close / sma200 - 1) * 100) : null, vs_sma50: sma50 ? r2((close / sma50 - 1) * 100) : null, rsi: r2(rsi), ret_20d_vs_qqq: r20 != null ? r2((r20 - qqq20) * 100) : null, vol_z: r2(volz), rsi_prev_max: r2(rsiPrevMax) };
  }
  let s = null, delta = null;
  if (news != null) {
    const conf = Math.min(1, cnt / 10);
    s = 50 + (clamp(50 + news * 100) - 50) * conf;
    if (base != null) { delta = news - base; s = clamp(s + clamp(delta * 50, -10, 10)); }
    s = clamp(s);
  }
  reasons.sentiment = { news_7d: news, base_30d: base, delta: delta == null ? null : Math.round(delta * 1000) / 1000, articles: cnt };
  // Value v1: price against growth, quality, balance sheet. Only inputs that exist count; coverage says how many did.
  const f = r.fund || {};
  const fn = (k) => num(f[k]);
  const growth = fn('rev_growth') != null ? fn('rev_growth') : fn('rev_growth_q');
  const vparts = {};
  if (growth != null) vparts.growth = clamp((growth * 100 - 10) / 4, -15, 15);
  if (fn('pe') != null && fn('pe') > 0) { const g = clamp(Math.max(fn('eps_growth') ?? 0, growth ?? 0, 0.05) * 100, 5, 100); vparts.price = clamp((1 - fn('pe') / g) * 15, -15, 15); }
  else if (fn('ps') != null && fn('ps') > 0 && growth != null) { const ratio = fn('ps') / (clamp(growth * 100, 5, 150) / 10); vparts.price = clamp((5 - ratio) * 2, -15, 15); }
  if (fn('gm') != null) vparts.gross_margin = clamp((fn('gm') * 100 - 40) / 4, -10, 10);
  if (fn('om') != null) vparts.op_margin = clamp(fn('om') * 100 / 5, -10, 10);
  if (fn('de') != null) vparts.debt = clamp((0.5 - fn('de')) * 10, -8, 8);
  if (fn('cr') != null) vparts.liquidity = clamp((fn('cr') - 1.5) * 4, -6, 6);
  const vkeys = Object.keys(vparts);
  const vcov = vkeys.length / 6;
  let v = null;
  if (vcov >= 0.5) v = clamp(50 + vkeys.reduce((a, k) => a + vparts[k], 0));
  reasons.value = { pe: fn('pe'), ps: fn('ps'), rev_growth: growth == null ? null : r2(growth * 100), eps_growth: fn('eps_growth') == null ? null : r2(fn('eps_growth') * 100), gross_margin: fn('gm') == null ? null : r2(fn('gm') * 100), op_margin: fn('om') == null ? null : r2(fn('om') * 100), debt_equity: fn('de'), current_ratio: fn('cr'), as_of: f.as_of || null, coverage: r2(vcov), parts: Object.fromEntries(vkeys.map(k => [k, r2(vparts[k])])) };
  // Catalyst v1: scheduled events, last surprise, news surge, open-market insider flow, analyst stance. Signed parts, coverage counts inputs present.
  const ne = r.next_earnings && r.next_earnings.date ? r.next_earnings : null;
  const earnDays = ne ? Math.round((new Date(ne.date + 'T00:00:00Z') - new Date(ctx.as_of + 'T00:00:00Z')) / 86400000) : null;
  const le = r.last_earnings && r.last_earnings.date ? r.last_earnings : null;
  const sinceEarn = le ? Math.round((new Date(ctx.as_of + 'T00:00:00Z') - new Date(le.date + 'T00:00:00Z')) / 86400000) : null;
  const cparts = {}, cin = {};
  if (earnDays != null) { cparts.earnings_ahead = earnDays <= 14 ? 8 : (earnDays <= 30 ? 4 : 0); cin.earnings_in_days = earnDays; }
  if (le && sinceEarn != null && sinceEarn <= 45 && num(le.surprise_pct) != null) { cparts.surprise = clamp(num(le.surprise_pct) / 2, -10, 10); cin.surprise_pct = num(le.surprise_pct); cin.surprise_days_ago = sinceEarn; }
  const rate = rateOf(r);
  if (rate != null && medRate) { const rel = rate / medRate; cin.news_rate = r2(rate); cin.news_rate_rel = r2(rel); cparts.news_surge = volz != null && volz > 1 ? clamp((rel - 1) * 8, -4, 12) : clamp((rel - 1) * 4, -4, 4); }
  const ins = r.insiders || null;
  if (ins && (num(ins.buys) || num(ins.sells))) { const bv = num(ins.buy_value) || 0, sv = num(ins.sell_value) || 0; const net = bv - sv; cin.insider_net_usd = Math.round(net); cin.insider_buys = num(ins.buys); cin.insider_sells = num(ins.sells); cparts.insiders = net >= 0 ? clamp(Math.log10(1 + net / 1e5) * 4, 0, 12) : clamp(-Math.log10(1 + -net / 1e6) * 3, -8, 0); }
  const recs = Array.isArray(r.recs) ? r.recs : [];
  const buyPct = (x) => { const tot = (num(x.sb) || 0) + (num(x.b) || 0) + (num(x.h) || 0) + (num(x.s) || 0) + (num(x.ss) || 0); return tot >= 3 ? ((num(x.sb) || 0) + (num(x.b) || 0)) / tot : null; };
  if (recs.length && buyPct(recs[0]) != null) { const bp = buyPct(recs[0]); cin.analyst_buy_pct = r2(bp * 100); cparts.analysts = clamp((bp * 100 - 50) / 5, -6, 6); if (recs[1] && buyPct(recs[1]) != null) { const d = bp - buyPct(recs[1]); cin.analyst_buy_pct_delta = r2(d * 100); cparts.analyst_shift = clamp(d * 40, -6, 6); } }
  const ckeys = Object.keys(cparts);
  const ccov = ckeys.length / 6;
  let c = null;
  if (ccov >= 0.5) c = clamp(50 + ckeys.reduce((a, k) => a + cparts[k], 0));
  reasons.catalyst = { ...cin, coverage: r2(ccov), parts: Object.fromEntries(ckeys.map(k => [k, r2(cparts[k])])) };
  const coverage = { momentum: m != null, sentiment: s != null, value: v != null, value_inputs: r2(vcov), catalyst: c != null, catalyst_inputs: r2(ccov) };
  const parts = [[m, w.momentum], [s, w.sentiment], [v, w.value], [c, w.catalyst]].filter(p => p[0] != null);
  const wsum = parts.reduce((a, p) => a + p[1], 0);
  const composite = wsum ? parts.reduce((a, p) => a + p[0] * p[1], 0) / wsum : null;
  const flags = [], risks = [];
  if (close != null && sma200 && sma20 && rsi != null && close > sma200 && close < sma20 && rsi >= 35 && rsi <= 45 && (news == null || news >= -0.1)) flags.push('pullback-in-uptrend');
  if (rsi != null && rsi < 30 && volz != null && volz > 1.5) flags.push('oversold-bounce');
  const bo = hi20 && close != null && close > hi20 && volz != null && volz > 2 && (delta == null || delta >= 0); const rsiDiv = rsi != null && rsiPrevMax != null && rsi < rsiPrevMax; if (bo && !rsiDiv) flags.push('breakout'); else if (bo && rsiDiv) risks.push('breakout-exhaustion');
  if (r.target_entry != null && close != null && Math.abs(close / Number(r.target_entry) - 1) <= 0.03) flags.push('near-target');
  if (delta != null && delta < -0.3) risks.push('sentiment-collapse');
  if (fromHi != null && fromHi < -0.5) risks.push('down-50pct-from-52w-high');
  // Earnings inside the next 7 calendar days (about 5 sessions) is a risk for any new entry.
  if (earnDays != null && earnDays <= 7) risks.push('earnings-soon');
  reasons.earnings = { next: ne ? ne.date : null, hour: ne ? (ne.hour || null) : null, days: earnDays, last_surprise_pct: r.last_earnings ? r.last_earnings.surprise_pct : null };
  if (r1 != null && Math.abs(r1) >= 0.1) risks.push(r1 > 0 ? 'gap-up-10pct' : 'gap-down-10pct');
  rows.push({ ticker: r.ticker, tags: r.tags || [], as_of: ctx.as_of, momentum: r2(m), value: r2(v), sentiment: r2(s), catalyst: r2(c), composite: r2(composite), flags, risks, reasons, score_version: SCORE_VERSION, coverage, close, r1, r5, r20, rsi: r2(rsi), volz: r2(volz), cnt, news, top_news: r.top_news || [], earn: reasons.earnings, missing_price: close == null });
}
rows.sort((a, b) => (b.composite ?? -1) - (a.composite ?? -1));
return [{ json: { run_id: ctx.run_id, as_of: ctx.as_of, rows, bench, count: rows.length } }];

const S = $('Score v2').first().json;
const ctx = $('Build context').first().json;
const sub = (name) => { try { return $(name).first().json; } catch (e) { return {}; } };
const prices = sub('Collect-Prices'), ind = sub('Compute-Indicators'), news = sub('Collect-News'), earn = sub('Collect-Earnings'), fund = sub('Collect-Fundamentals'), sig = sub('Collect-Signals');
const pct = (v) => (v == null ? '' : (v * 100 >= 0 ? '+' : '') + (v * 100).toFixed(1) + '%');
const n1 = (v) => (v == null ? '' : Number(v).toFixed(1));
const n2 = (v) => (v == null ? '' : Number(v).toFixed(2));
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const rows = S.rows, B = S.bench || {};
const holdings = rows.filter(r => r.tags.includes('holding'));
const setups = rows.filter(r => r.flags.length).slice(0, 5);
const risky = rows.filter(r => r.risks.length);
const missing = rows.filter(r => r.missing_price).map(r => r.ticker);
// Run status from what the collectors really returned.
const issues = [];
if (ctx.calendar_ok === false) issues.push('calendar unavailable, weekday fallback');
if (prices.ok !== true) issues.push('prices failed' + (prices.error ? ': ' + String(prices.error).slice(0, 120) : ''));
if (ind.ok !== true) issues.push('indicators failed');
if (news.ok !== true) issues.push('news failed');
else if (news.finnhub_failed) issues.push(`finnhub failed for ${news.finnhub_failed}: ${(news.finnhub_failed_tickers || []).slice(0, 8).join(' ')}`);
if (earn.ok !== true) issues.push('earnings failed');
else if (earn.failed) issues.push(`earnings failed for ${earn.failed}: ${(earn.failed_tickers || []).slice(0, 8).join(' ')}`);
if (fund.ok !== true) issues.push('fundamentals failed');
else if (fund.failed) issues.push(`fundamentals failed for ${fund.failed}: ${(fund.failed_tickers || []).slice(0, 8).join(' ')}`);
if (sig.ok !== true) issues.push('signals failed');
else if (sig.failed) issues.push(`signals failed for ${sig.failed} calls: ${(sig.failed_tickers || []).slice(0, 8).join(' ')}`);
if (news.av_errors) issues.push(`alphavantage errors: ${news.av_errors}`);
if (news.av_calls && news.av_throttled === news.av_calls && !ctx.av_ok_today) issues.push('alphavantage fully throttled, no sentiment today');
if (missing.length) issues.push(`no price for ${missing.length}: ${missing.slice(0, 8).join(' ')}`);
if (sub('Upsert scores_daily').error) issues.push('scores not stored');
const priced = rows.length - missing.length;
const status = priced === 0 ? 'failed' : (issues.length ? 'degraded' : 'ok');

let md = `# Stock Intel brief, ${S.as_of}\n\n`;
md += `## Market context\n\n| Index | 1d | 5d | 20d | RSI |\n|---|---|---|---|---|\n`;
for (const t of ['SPY', 'QQQ', 'SOXX', 'ARKX', 'UFO']) { const b = B[t]; if (b) md += `| ${t} | ${pct(b.ret_1d)} | ${pct(b.ret_5d)} | ${pct(b.ret_20d)} | ${n1(b.rsi14)} |\n`; }
const line = (r) => `| ${r.ticker} | ${n2(r.close)} | ${pct(r.r1)} | ${pct(r.r5)} | ${pct(r.r20)} | ${n1(r.rsi)} | ${n1(r.volz)} | ${r.news == null ? '' : n2(r.news)} (${r.cnt}) | ${r.momentum == null ? '' : n1(r.momentum)} | ${r.value == null ? '' : n1(r.value)} | ${r.catalyst == null ? '' : n1(r.catalyst)} | ${n1(r.composite)} | ${r.flags.join(', ')} |`;
const hdr = `| Ticker | Close | 1d | 5d | 20d | RSI | Vol z | Sent 7d (n) | Mom | Value | Cat | Score | Flags |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|`;
// Share counts and dollar values only reach the email when email_position_values is on.
const pos = ctx.positions || {}, showVals = ctx.email_position_values === true;
const hHdr = showVals
  ? `| Ticker | Shares | Avg cost | Close | Value | Gain | 1d | 5d | 20d | RSI | Score | Flags |\n|---|---|---|---|---|---|---|---|---|---|---|---|`
  : hdr;
const hLine = (r) => {
  if (!showVals) return line(r);
  const p = pos[r.ticker] || {};
  const qty = p.qty == null ? null : Number(p.qty);
  const cost = p.avg_cost == null ? null : Number(p.avg_cost);
  const val = (qty == null || r.close == null) ? null : qty * r.close;
  const gain = (qty == null || cost == null || r.close == null) ? null : qty * (r.close - cost);
  return `| ${r.ticker} | ${qty == null ? '' : qty.toFixed(3)} | ${n2(cost)} | ${n2(r.close)} | ${n2(val)} | ${n2(gain)} | ${pct(r.r1)} | ${pct(r.r5)} | ${pct(r.r20)} | ${n1(r.rsi)} | ${n1(r.composite)} | ${r.flags.join(', ')} |`;
};
md += `\n## Holdings\n\n${hHdr}\n${holdings.map(hLine).join('\n')}\n`;
// Next 14 days of reports; holdings first. Unknown dates are said out loud.
const hourTxt = { bmo: 'before open', amc: 'after close', dmh: 'during hours' };
const upcoming = rows.filter(r => r.earn && r.earn.days != null && r.earn.days <= 14).sort((x, y) => x.earn.days - y.earn.days);
const noDate = holdings.filter(r => !r.earn || !r.earn.next).map(r => r.ticker);
md += `\n## Earnings, next 14 days\n\n`;
md += upcoming.length ? `| Ticker | Date | When | In | Last surprise | Held |\n|---|---|---|---|---|---|\n` + upcoming.map(r => `| ${r.ticker} | ${r.earn.next} | ${hourTxt[r.earn.hour] || ''} | ${r.earn.days}d | ${r.earn.last_surprise_pct == null ? '' : n1(r.earn.last_surprise_pct) + '%'} | ${r.tags.includes('holding') ? 'yes' : ''} |`).join('\n') + `\n` : `None scheduled.\n`;
if (noDate.length) md += `\nNo earnings date known for holdings: ${noDate.join(', ')}.\n`;
md += `\n## Entry setups\n\n`;
if (!setups.length) md += `None today.\n`;
for (const r of setups) {
  const m = r.reasons.momentum || {}, s = r.reasons.sentiment || {};
  md += `**${r.ticker}** ${r.flags.join(', ')} (score ${n1(r.composite)}). Close ${n2(r.close)}, ${m.vs_sma200 != null ? m.vs_sma200 + '% vs SMA200, ' : ''}RSI ${n1(r.rsi)}, vol z ${n1(r.volz)}, sentiment ${s.news_7d == null ? 'n/a' : n2(s.news_7d) + ' on ' + s.articles + ' articles'}${s.delta != null ? ' (delta ' + s.delta + ')' : ''}.\n`;
  for (const a of (r.top_news || []).slice(0, 2)) md += `  - ${a.h}${a.s != null ? ' [' + n2(a.s) + ']' : ''}\n`;
  md += `\n`;
}
md += `\n## Watchlist\n\n${hdr}\n${rows.filter(r => !r.tags.includes('holding')).map(line).join('\n')}\n`;
md += `\n## Risk flags\n\n${risky.length ? risky.map(r => `- ${r.ticker}: ${r.risks.join(', ')}`).join('\n') : 'None.'}\n`;
md += `\n---\nrun ${S.run_id}. prices ${prices.rows ?? '?'} rows / ${prices.symbols ?? '?'} symbols; indicators ${ind.rows ?? '?'}; news finnhub ${news.finnhub_rows ?? '?'}, alphavantage ${news.av_rows ?? '?'} (${news.av_throttled ?? 0} throttled); earnings ${earn.rows ?? '?'} rows; fundamentals ${fund.rows ?? '?'} rows; insiders ${sig.insider_rows ?? '?'}, recs ${sig.rec_rows ?? '?'}.${missing.length ? ' No price for: ' + missing.join(', ') + '.' : ''}${status === 'ok' ? '' : '\nRun status: ' + status + '. ' + issues.join('; ') + '.'}\nFramework, not advice. Scores v2 = momentum + sentiment + growth-adjusted value + catalyst (each only where at least half its inputs exist; value ${rows.filter(r => r.value != null).length}, catalyst ${rows.filter(r => r.catalyst != null).length} of ${rows.length} today).\n`;

// minimal HTML rendering of the markdown tables/headings
const html = md.split('\n').map((l) => {
  if (l.startsWith('# ')) return `<h2>${esc(l.slice(2))}</h2>`;
  if (l.startsWith('## ')) return `<h3>${esc(l.slice(3))}</h3>`;
  if (/^\|---/.test(l)) return '';
  if (l.startsWith('|')) { const cells = l.slice(1, -1).split('|').map(c => c.trim()); const tag = /^\| Ticker|^\| Index/.test(l) ? 'th' : 'td'; return `<tr>${cells.map(c => `<${tag} style="padding:2px 8px;border-bottom:1px solid #ddd;text-align:right;font-family:monospace;font-size:12px">${esc(c)}</${tag}>`).join('')}</tr>`; }
  if (l.startsWith('- ') || l.startsWith('  - ')) return `<div style="margin-left:16px">&bull; ${esc(l.replace(/^\s*- /, ''))}</div>`;
  if (l === '---') return '<hr>';
  if (l.startsWith('**')) return `<p>${esc(l).replace(/\*\*(.+?)\*\*/, '<b>$1</b>')}</p>`;
  return l ? `<p>${esc(l)}</p>` : '';
}).join('\n').replace(/(<tr>[\s\S]*?<\/tr>\n?)+/g, (t) => `<table style="border-collapse:collapse">${t}</table>`);
// Telegram message: the headline facts only. Telegram caps a message at 4096 chars,
// and the full brief rides along as a .md attachment when send_document is on.
const tgMovers = [...rows].filter(r => r.ret_1d != null).sort((a, b) => Math.abs(b.ret_1d) - Math.abs(a.ret_1d)).slice(0, 5);
const tgLines = [
  `Stock Intel ${S.as_of}`,
  `${setups.length} setup${setups.length === 1 ? '' : 's'}, ${risky.length} risk flag${risky.length === 1 ? '' : 's'}, run ${status}`,
  '',
  'Movers: ' + (tgMovers.map(r => `${r.ticker} ${(r.ret_1d * 100).toFixed(1)}%`).join(', ') || 'none priced'),
  'Setups: ' + (setups.map(r => `${r.ticker} (${(r.flags || []).join('/')})`).join(', ') || 'none'),
  'Risks: ' + (risky.map(r => `${r.ticker} (${(r.risks || []).join('/')})`).join(', ') || 'none'),
];
if (issues.length) tgLines.push('', 'Issues: ' + issues.join('; '));
const telegram_text = tgLines.join('
').slice(0, 3900);

const subject = `Stock Intel ${S.as_of}: ${setups.length} setup${setups.length === 1 ? '' : 's'}, ${risky.length} risk flag${risky.length === 1 ? '' : 's'}`;
return [{ json: { run_id: S.run_id, as_of: S.as_of, subject, telegram_text, markdown: md, html: `<div style="font-family:system-ui,sans-serif;font-size:14px">${html}</div>`, status, summary: { status, issues, setups: setups.map(r => r.ticker), risks: risky.map(r => r.ticker), missing, prices, ind, news, earn, earnings_soon: upcoming.filter(r => r.earn.days <= 7).map(r => r.ticker) } } }];

parameters.query:
INSERT INTO intel.reports (as_of, run_id, markdown, html, sent_to, sent_at)
VALUES ($2::date, $1::uuid, $3, $4,
        CASE WHEN $6::boolean THEN ARRAY['telegram'] ELSE ARRAY[]::text[] END,
        CASE WHEN $6::boolean THEN now() ELSE NULL END)
ON CONFLICT (as_of) DO UPDATE SET run_id = EXCLUDED.run_id, markdown = EXCLUDED.markdown, html = EXCLUDED.html, sent_to = EXCLUDED.sent_to, sent_at = EXCLUDED.sent_at;
UPDATE intel.runs SET finished_at = now(), status = $7, summary = $5::jsonb WHERE run_id = $1::uuid;

